/// [RFC 8032, section 7.1][rfc8032-7.1], TEST 1 to 3: secret key to public key.
///
/// [rfc8032-7.1]: https://www.rfc-editor.org/rfc/rfc8032#section-7.1
#[test]
fn rfc8032_vectors() {
    let cases = [
        (
            "9d61b19deffd5a60ba844af492ec2cc44449c5697b326919703bac031cae7f60",
            "d75a980182b10ab7d54bfed3c964073a0ee172f3daa62325af021a68f707511a",
        ),
        (
            "4ccd089b28ff96da9db6c346ec114e0f5b8a319f35aba624da8cf6ed4fb8a6fb",
            "3d4017c3e843895a92b70aa74d1b7ebc9c982ccf2ec4968cc0cd55f12af4660c",
        ),
        (
            "c5aa8df43f9f837bedb7442f31dcb7b166d38535076f094b85ce3a2e0b4458f7",
            "fc51cd8e6218a1a38da47ed00230f0580816ed13ba3303ac5deb911548908025",
        ),
    ];
    for (secret, public) in cases {
        assert_eq!(
            Ed25519::public_key(&array(secret)),
            hex(public),
            "{secret}"
        );
    }
}

/// Public keys of seeds generated by OpenSSL (`scripts/gen-ec-vectors.sh`).
#[test]
fn openssl_key_pairs() {
    let mut seen = 0;
    for line in fixture("keys/keypairs.txt").lines() {
        if let ["ED25519", private, public, ..] =
            line.split_whitespace().collect::<Vec<_>>()[..]
        {
            assert_eq!(
                Ed25519::public_key(&array(private)),
                hex(public),
                "{private}"
            );
            seen += 1;
        }
    }
    assert_eq!(seen, 4);
}

/// The secret scalar is clamped: a multiple of 8, below 2^255, at least 2^254.
#[test]
fn clamping() {
    for byte in [0u8, 0x55, 0xff] {
        // Big-endian: the low byte is the last.
        let s = Ed25519::secret_scalar(&[byte; 32]);
        let s = s.expose();
        assert_eq!(s.len(), 32);
        assert_eq!(s[31] & 7, 0);
        assert_eq!(s[0] & 0x80, 0);
        assert_eq!(s[0] & 0x40, 0x40);
    }
}

/// The public key is the exponential map composed with the key expansion:
/// `public_key = encode([secret_scalar] B)`, written out here rather than
/// through the provided method. The secret scalar is a multiple of the
/// cofactor, so the public key lies in the prime-order subgroup.
#[test]
fn public_key_is_the_exponential_of_the_secret_scalar() {
    for byte in [0u8, 1, 0x55, 0xff] {
        let seed = [byte; 32];
        let s = Ed25519::secret_scalar(&seed);
        let a = Edwards25519::scalar_mul_bytes(
            &Extended::<Edwards25519>::generator(),
            s.expose(),
        );
        assert!(a.is_in_prime_subgroup().to_bool_vartime());
        assert_eq!(Ed25519::public_key(&seed), a.to_affine().encode());
    }
}

