/// Each RFC test signs to the RFC's signature exactly, verifies, and the
/// signature reads back.
#[test]
fn rfc8032_signatures() {
    for case in RFC8032 {
        let pair =
            EdDsaKeyPair::<Ed25519Parameters>::from_seed(array(case.secret));
        assert_eq!(
            pair.public().as_bytes(),
            hex(case.public).as_slice(),
            "{}",
            case.name
        );
        let message = hex(case.message);
        let signature = Ed25519::sign(&pair, &message).unwrap();
        assert_eq!(
            signature.encode(),
            hex(case.signature),
            "TEST {}",
            case.name
        );
        let key =
            PublicKey::<Ed25519Parameters>::decode(&hex(case.public)).unwrap();
        assert!(
            Ed25519::verify(&key, &message, &signature),
            "TEST {}",
            case.name
        );
        assert_eq!(
            Signature::<Ed25519Parameters>::decode(&hex(case.signature)),
            Ok(signature)
        );
    }
}

/// Correctness and determinism for any seed and message, and rejection when
/// any one bit of the message, of $R$, of $S$ or of the key changes.
fn laws(seed: [u8; 32], message: &[u8], bit: usize) {
    let pair = EdDsaKeyPair::<Ed25519Parameters>::from_seed(seed);
    let key = PublicKey::<Ed25519Parameters>::decode(pair.public().as_bytes())
        .unwrap();
    let signature = Ed25519::sign(&pair, message).unwrap();
    assert!(Ed25519::verify(&key, message, &signature));
    assert_eq!(Ed25519::sign(&pair, message).unwrap(), signature);
    let encoded = signature.encode();
    let mut flipped = encoded.clone();
    flipped[(bit / 8) % 64] ^= 1 << (bit % 8);
    if let Ok(changed) = Signature::<Ed25519Parameters>::decode(&flipped) {
        assert!(!Ed25519::verify(&key, message, &changed), "signature bit");
    }
    let mut other = message.to_vec();
    if other.is_empty() {
        other.push(0);
    } else {
        let i = (bit / 8) % other.len();
        other[i] ^= 1 << (bit % 8);
    }
    assert!(!Ed25519::verify(&key, &other, &signature), "message bit");
    let mut key_bytes = pair.public().as_bytes().to_vec();
    key_bytes[(bit / 8) % 32] ^= 1 << (bit % 8);
    if let Ok(other_key) = PublicKey::<Ed25519Parameters>::decode(&key_bytes) {
        assert!(!Ed25519::verify(&other_key, message, &signature), "key bit");
    }
}

proptest! {
    #![proptest_config(ProptestConfig::with_cases(32))]

    #[test]
    fn signature_laws(
        seed in any::<[u8; 32]>(),
        message in prop::collection::vec(any::<u8>(), 0..300),
        bit in any::<usize>(),
    ) {
        laws(seed, &message, bit);
    }

    /// The decoders of signatures and of public keys are canonical: on
    /// arbitrary bytes, and on valid encodings with one bit flipped,
    /// whatever decodes re-encodes to the same bytes. (A public key keeps
    /// the bytes it was read from, the ones the challenge hash covers.)
    #[test]
    fn decoders_are_canonical(
        bytes in prop::collection::vec(any::<u8>(), 0..80),
        seed in any::<[u8; 32]>(),
        message in prop::collection::vec(any::<u8>(), 0..64),
        bit in any::<usize>(),
    ) {
        canonical::<Signature<Ed25519Parameters>>(&bytes);
        canonical::<PublicKey<Ed25519Parameters>>(&bytes);
        let pair = EdDsaKeyPair::<Ed25519Parameters>::from_seed(seed);
        let valid = [
            Ed25519::sign(&pair, &message).unwrap().encode(),
            pair.public().as_bytes().to_vec(),
        ];
        for encoding in valid {
            canonical::<Signature<Ed25519Parameters>>(&encoding);
            canonical::<PublicKey<Ed25519Parameters>>(&encoding);
            let mut flipped = encoding.clone();
            let i = (bit / 8) % flipped.len();
            flipped[i] ^= 1 << (bit % 8);
            canonical::<Signature<Ed25519Parameters>>(&flipped);
            canonical::<PublicKey<Ed25519Parameters>>(&flipped);
        }
    }
}

/// $S \geq \ell$ is rejected (section 5.1.7), and so is a signature of
/// another length; the empty message and messages of 1023 and 1024 bytes
/// sign and verify.
#[test]
fn encoding_and_boundaries() {
    let decode = Signature::<Ed25519Parameters>::decode;
    let mut ell_le = <Edwards25519 as Curve>::Scalar::modulus_be();
    ell_le.reverse();
    let mut at_ell = vec![0u8; 32];
    at_ell.extend(&ell_le);
    assert_eq!(decode(&at_ell), Err(InvalidEncoding), "S = l");
    let mut below = at_ell.clone();
    below[32] -= 1;
    assert!(decode(&below).is_ok(), "S = l - 1");
    assert_eq!(decode(&[0u8; 63]), Err(InvalidEncoding), "63 bytes");
    assert_eq!(decode(&[0u8; 65]), Err(InvalidEncoding), "65 bytes");
    for len in [0usize, 1023, 1024] {
        laws([7u8; 32], &vec![0xa5; len], len);
    }
}

/// baldssl's verdict on a signature given as bytes: a key or a signature
/// that does not decode is invalid.
fn verdict(message: &[u8], key: &[u8], signature: &[u8]) -> &'static str {
    let key = PublicKey::<Ed25519Parameters>::decode(key);
    let signature = Signature::<Ed25519Parameters>::decode(signature);
    match (key, signature) {
        (Ok(k), Ok(s)) if Ed25519::verify(&k, message, &s) => "valid",
        _ => "invalid",
    }
}

/// The edge cases of Chalkias, Garillot and Nikolaenko, "Taming the many
/// EdDSAs" ([ePrint 2020/1244]): small-order keys and nonces, non-canonical
/// encodings, the cofactored against the cofactorless equation, $S \geq
/// \ell$. baldssl gives OpenSSL's verdict on every one
/// (`ed25519/edge-cases.txt`, `scripts/gen-ed25519-vectors.py`; OpenSSL 3.5
/// and 4.1 agree).
///
/// [ePrint 2020/1244]: https://eprint.iacr.org/2020/1244
#[test]
fn openssl_verdicts_on_edge_cases() {
    let text = fixture("ed25519/edge-cases.txt");
    let mut seen = 0;
    for line in text.lines().filter(|l| !l.starts_with('#')) {
        let f: Vec<&str> = line.split(' ').collect();
        assert_eq!(
            verdict(&hex(f[2]), &hex(f[3]), &hex(f[4])),
            f[1],
            "case {}",
            f[0]
        );
        seen += 1;
    }
    assert_eq!(seen, 12);
}

/// Signatures made by OpenSSL (`ed25519/openssl-signatures.txt`) verify,
/// and are the ones baldssl makes: Ed25519 signing is deterministic.
#[test]
fn openssl_signatures() {
    let text = fixture("ed25519/openssl-signatures.txt");
    let keys = fixture("keys/keypairs.txt");
    let mut count = 0;
    for line in text.lines().filter(|l| !l.starts_with('#')) {
        let f: Vec<&str> = line.split(' ').collect();
        let (message, key, expected) = (hex(f[0]), hex(f[1]), hex(f[2]));
        assert_eq!(verdict(&message, &key, &expected), "valid", "{line}");
        let seed = keys
            .lines()
            .map(|l| l.split(' ').collect::<Vec<_>>())
            .find(|k| k[0] == "ED25519" && k[2] == f[1])
            .map(|k| array::<32>(k[1]))
            .unwrap();
        let pair = EdDsaKeyPair::<Ed25519Parameters>::from_seed(seed);
        assert_eq!(Ed25519::sign(&pair, &message).unwrap().encode(), expected);
        count += 1;
    }
    assert_eq!(count, 12);
}
